sys_script.script:
(function executeRule(current, previous) {
    // Abort if name is blank — enforced by the BR condition above.
    gs.addErrorMessage('CatalogForge draft name is required.');
})(current, previous);

sysauto_script.script:
(function() {
    var cutoff = new GlideDateTime();
    cutoff.addDays(-30);
    var gr = new GlideRecord('x_sncf_catalog_forge_draft');
    gr.addQuery('status', 'proposed');
    gr.addQuery('sys_created_on', '<', cutoff.getDisplayValue());
    gr.query();
    var count = 0;
    while (gr.next()) {
        try {
            gr.deleteRecord();
            count++;
        } catch (e) {
            gs.error('CatalogForge housekeeping failed on draft ' + gr.getUniqueValue() + ': ' + e);
        }
    }
    gs.info('CatalogForge housekeeping purged ' + count + ' stale draft(s)');
})();
